/**
 * The now-sdk command catalogue.
 *
 * Generated by reading `now-sdk --help` and every subcommand's `--help` at
 * **4.9.2**, then hand-classifying two things a help string cannot tell you:
 *
 *  1. `risk` — you cannot derive "this writes to a production instance"
 *     from yargs output. `install` reaches the instance; `build` does not.
 *     Anything absent from this manifest defaults to always-ask.
 *  2. `picker` — WHICH picker resolves a flag's value. This is the whole
 *     point of the Project pane: nobody should have to go and find a sys_id.
 *
 * Regenerating: run `now-sdk --help` and `now-sdk <cmd> --help` for each
 * command and diff against this table.
 */

export const MANIFEST_SDK_VERSION = '4.9.2'

/** What resolves a flag's value in the UI. */
export type PickerKind =
  | 'app-scope' // sys_app records → sys_id
  | 'auth-alias' // now-sdk auth --list
  | 'directory' // local directory tree
  | 'enum' // fixed choices from --help
  | 'none' // free text
  | 'scope-name' // global | x_... (validated)
  | 'table' // sys_db_object
  | 'table-multi' // comma-separated table names

export type SdkRisk =
  /** Reaches the instance — always-ask, same tier as xml import. */
  | 'instance'
  /** Local only — no approval. */
  | 'local'
  /** Writes local files — confirm overwrites. */
  | 'local-write'

export interface SdkFlag {
  choices?: string[]
  /** Short description lifted from --help. */
  description: string
  name: string
  picker: PickerKind
  /** Positional argument rather than a --flag. */
  positional?: boolean
  required?: boolean
  type: 'boolean' | 'number' | 'string'
  /** Regex the value must satisfy, with a human explanation. */
  validate?: { message: string; pattern: RegExp }
}

export interface SdkCommand {
  flags: SdkFlag[]
  /** Prompts via @inquirer/prompts — must use the foreground handoff. */
  interactive?: boolean
  name: string
  /** npm script that wraps this command, when the project defines one. */
  npmScript?: 'build' | 'deploy'
  risk: SdkRisk
  summary: string
}

/** now.config.json's own schema for `scope`. Enforce before spawning. */
export const SCOPE_NAME_PATTERN = /^((sn|x)_[\da-z_]+|global)$/
export const SCOPE_NAME_MAX = 18

