/**
 * Commands that prompt and therefore need the foreground handoff. `auth
 * --add` asks for a password via @inquirer/prompts; the TUI deliberately
 * does not collect credentials itself, so it is not offered as a form —
 * it is handed the terminal. `init` prompts when required options are
 * missing, which the pane avoids by resolving them up front.
 */
export const INTERACTIVE_COMMANDS = new Set(['auth'])

export function findCommand(name: string): SdkCommand | undefined {
  return SDK_COMMANDS.find((c) => c.name === name)
}

/**
 * Risk for a command name. Unknown commands are treated as
 * instance-reaching: the safe default when the manifest is out of date
 * relative to the installed SDK.
 */
export function riskFor(name: string): SdkRisk {
  return findCommand(name)?.risk ?? 'instance'
}

export function validateFlagValue(flag: SdkFlag, value: string): string | undefined {
  if (flag.picker === 'scope-name' && value.length > SCOPE_NAME_MAX) {
    return `${value.length} characters — the maximum is ${SCOPE_NAME_MAX}`
  }

  if (flag.validate && value.length > 0 && !flag.validate.pattern.test(value)) {
    return flag.validate.message
  }

  if (flag.choices && value.length > 0 && !flag.choices.includes(value)) {
    return `must be one of: ${flag.choices.join(', ')}`
  }

  return undefined
}

/** Build the argv for a command from resolved flag values. */
export function buildArgv(command: SdkCommand, values: Record<string, string>): string[] {
  const argv: string[] = [command.name]
  for (const flag of command.flags) {
    const value = values[flag.name]
    if (value === undefined || value === '') continue
    if (flag.positional) {
      argv.push(value)
    } else if (flag.type === 'boolean') {
      if (value === 'true') argv.push(`--${flag.name}`)
    } else {
      argv.push(`--${flag.name}`, value)
    }
  }

  return argv
}
